namespace Cratis.Chronicle.Tools.GrainCompatibility.for_ContractManifest.when_parsing;

public class and_it_is_a_manifest_the_analyzer_wrote : Specification
{
    const string Manifest = """
        # This file is generated by the Orleans contract analyzer.
        # OrleansContracts format: 2

        class [GrainType("projectionsmanager")] Cratis.Chronicle.Projections.ProjectionsManager

        interface [GrainInterfaceType("Cratis.Chronicle.Projections.IProjectionsManager")] Cratis.Chronicle.Projections.IProjectionsManager [Version(3)]
          E36EB1EC: Ensure() -> Task
          F436C56F: Register(System.Collections.Generic.IEnumerable<Cratis.Chronicle.Concepts.Projections.Definitions.ProjectionDefinition>, Cratis.Chronicle.Concepts.Projections.ProjectionOwner?, string?, string?) -> Task
          with\: colon: Aliased() -> Task

        *RETIRED* interface [GrainInterfaceType("Cratis.Chronicle.ILegacy")] Cratis.Chronicle.ILegacy [Version(0)]

        *RETIRED* class [GrainType("legacy")] Cratis.Chronicle.Legacy
        """;

    ContractManifest _manifest;
    GrainInterfaceContract _projectionsManager;

    void Because()
    {
        _manifest = ContractManifest.Parse(Manifest);
        _projectionsManager = _manifest.Interfaces["Cratis.Chronicle.Projections.IProjectionsManager"];
    }

    [Fact] void should_read_the_version() => _projectionsManager.Version.ShouldEqual(3);
    [Fact] void should_read_every_method() => _projectionsManager.Methods.Count.ShouldEqual(3);
    [Fact] void should_key_methods_by_wire_identity() => _projectionsManager.Methods["F436C56F"].Name.ShouldEqual("Register");
    [Fact] void should_keep_the_signature_without_the_name() => _projectionsManager.Methods["E36EB1EC"].Signature.ShouldEqual("() -> Task");
    [Fact] void should_unescape_an_identity() => _projectionsManager.Methods.ContainsKey("with: colon").ShouldBeTrue();
    [Fact] void should_read_a_retired_interface_as_retired() => _manifest.Interfaces["Cratis.Chronicle.ILegacy"].Retired.ShouldBeTrue();
    [Fact] void should_leave_retired_interfaces_out_of_the_active_ones() => _manifest.ActiveInterfaces.Count().ShouldEqual(1);
    [Fact] void should_read_the_grain_class() => _manifest.Classes["projectionsmanager"].Retired.ShouldBeFalse();
    [Fact] void should_read_a_retired_grain_class_as_retired() => _manifest.Classes["legacy"].Retired.ShouldBeTrue();
}
